 if(data.startsWith('admin:users:')){const off=Number(data.split(':')[2]),users=store.adminUsers(off),rows=users.map(u=>[btn(`${u.display_name||u.username||u.user_id} · ${u.user_id}`,`admin:user:${u.user_id}`)]);if(off)rows.push([btn('‹ Sebelumnya',`admin:users:${Math.max(0,off-20)}`)]);if(users.length===20)rows.push([btn('Berikutnya ›',`admin:users:${off+20}`)]);rows.push([btn('⬅️ Admin','admin:home')]);await showOrEdit(chat,msg,'Daftar pengguna:',keyboard(rows));return;}
 if(data.startsWith('admin:user:')){const uid=Number(data.split(':')[2]),u=store.getAdminUser(uid);if(!u){await send(chat,'Pengguna tidak ditemukan.');return;}const blocked=store.isBlocked(uid);await showOrEdit(chat,msg,`${u.display_name||u.username||uid}\nID: ${uid}\nFile berhasil: ${u.files_success}\nPanggilan AI: ${u.ai_calls}\nStatus: ${blocked?'DIBLOKIR':'aktif'}`,keyboard([[btn(blocked?'Buka blokir':'Blokir',`admin:${blocked?'unblock':'block'}:${uid}`)],[btn('Premium 30 hari','admin:premium:'+uid),btn('Hapus Premium','admin:revoke:'+uid)],[btn('🗑 Hapus pengguna','admin:delete:'+uid)],[btn('⬅️ Daftar pengguna','admin:users:0')]]));return;}
 if(data.startsWith('admin:block:')){store.setBlocked(Number(data.split(':')[2]),true);await send(chat,'Pengguna diblokir.');return;}
 if(data.startsWith('admin:unblock:')){store.setBlocked(Number(data.split(':')[2]),false);await send(chat,'Blokir dibuka.');return;}
